def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append((oid, opp))

    if not alive:
        base = DAILY_SALARY * 0.35
        if no_water_days >= 1 or hp <= 3:
            base = DAILY_SALARY * 0.75
        return float(max(0.0, min(budget, base)))

    cindy_bid = None
    highest_prev = 0.0
    urgent_opp = 0
    rich_opp = 0
    for oid, opp in alive:
        if opp.get('budget', 0) >= 120:
            rich_opp += 1
        if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 1:
            urgent_opp += 1
        prev = opp.get('previous_trace', {})
        if prev:
            pbid = prev.get('bid')
            if pbid is not None:
                if pbid > highest_prev:
                    highest_prev = pbid
                if oid == 'Cindy':
                    cindy_bid = pbid

    slots = max(1, int(supply // WATER_REQ))
    tight = slots <= 1

    if cindy_bid is None:
        cindy_bid = 150.0 if day <= 3 else 120.0

    if no_water_days >= 2 or hp <= 2:
        bid = min(budget, max(0.92 * DAILY_SALARY, cindy_bid + 3.0, highest_prev + 2.0))
        return float(max(0.0, bid))

    if tight:
        if no_water_days >= 1 or hp <= 4:
            target = max(cindy_bid + 2.5, highest_prev + 1.5, 0.88 * DAILY_SALARY)
        else:
            if cindy_bid >= 180:
                target = DAILY_SALARY * 0.22
            else:
                target = max(DAILY_SALARY * 0.52, min(cindy_bid + 1.0, DAILY_SALARY * 0.86))
    else:
        if no_water_days >= 1:
            target = max(DAILY_SALARY * 0.6, highest_prev * 0.7)
        else:
            target = DAILY_SALARY * 0.28
            if rich_opp >= 2 and highest_prev > 100:
                target = DAILY_SALARY * 0.18
            elif urgent_opp >= 2:
                target = DAILY_SALARY * 0.4

    days_left = max(1, 10 - day + 1)
    reserve_floor = max(0.0, (days_left - 2) * DAILY_SALARY * 0.18)
    spend_cap = max(0.0, budget - reserve_floor)
    if hp >= 7 and no_water_days == 0 and not tight:
        spend_cap = min(spend_cap, DAILY_SALARY * 0.45)

    bid = min(target, budget)
    if spend_cap > 0:
        bid = min(bid, max(spend_cap, DAILY_SALARY * 0.12) if (no_water_days >= 1 or hp <= 4) else max(DAILY_SALARY * 0.12, spend_cap))
    else:
        bid = min(bid, DAILY_SALARY * 0.2 if (hp >= 5 and no_water_days == 0) else budget)

    min_pressure = 0.0
    if no_water_days >= 1 or hp <= 4:
        min_pressure = DAILY_SALARY * 0.45
    elif tight and cindy_bid < 170:
        min_pressure = DAILY_SALARY * 0.35

    bid = max(min_pressure, bid)
    bid = min(bid, budget)
    if bid < 0:
        bid = 0.0
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    num_alive_opponents = len(alive_opponents)

    if num_alive_opponents == 0:
        return min(my_status['budget'], DAILY_SALARY * 0.3)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    current_day = day_context['day']
    remaining_days = EPISODE_DAYS - current_day
    day_aggression_multiplier = 1.0
    if remaining_days <= 2:
        day_aggression_multiplier = 1.15
    elif remaining_days <= 4:
        day_aggression_multiplier = 1.08

    hp_adjustment = 0.0
    if my_status['hp'] <= 2:
        hp_adjustment = DAILY_SALARY * 0.2
    elif my_status['hp'] <= 4:
        hp_adjustment = DAILY_SALARY * 0.1

    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)

        high_competition_threshold = DAILY_SALARY * 0.9 * day_aggression_multiplier

        if highest_prev_bid >= high_competition_threshold:
            if my_status['hp'] > 5:
                bid_amount = DAILY_SALARY * 0.7 * day_aggression_multiplier
                return min(my_status['budget'], bid_amount + hp_adjustment)
            else:
                bid_amount = max(highest_prev_bid + 5, DAILY_SALARY * 0.95)
                return min(my_status['budget'], (bid_amount + hp_adjustment) * day_aggression_multiplier)
        else:
            base_competitive_bid = DAILY_SALARY * 0.8
            bid_amount = max(base_competitive_bid, highest_prev_bid + 5)
            return min(my_status['budget'], (bid_amount + hp_adjustment) * day_aggression_multiplier)
    else:
        if my_status['hp'] <= 3:
            return min(my_status['budget'], (DAILY_SALARY * 0.95 + hp_adjustment) * day_aggression_multiplier)
        else:
            return min(my_status['budget'], (DAILY_SALARY * 0.8 + hp_adjustment) * day_aggression_multiplier)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    supply = day_context['supply']
    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_status['budget'], 10.0)

    cindy = opponents_status.get('Cindy', {})
    cindy_bid = 0.0
    if cindy.get('alive') and cindy.get('previous_trace'):
        cindy_bid = cindy['previous_trace'].get('bid', 0.0)

    if my_status['hp'] <= 3:
        target_bid = DAILY_SALARY * 0.9
    elif supply < 18:
        target_bid = max(cindy_bid + 2.0, DAILY_SALARY * 0.6)
    else:
        target_bid = max(cindy_bid * 0.5, DAILY_SALARY * 0.4)

    return float(min(my_status['budget'], target_bid))
